using System.Collections.Concurrent;

namespace UrlShortener.Core;

/// <summary>A shortened link; may optionally expire.</summary>
public sealed record Link(string Code, string TargetUrl, DateTimeOffset CreatedAt, DateTimeOffset? ExpiresAt = null)
{
    public bool IsExpired(DateTimeOffset now) => ExpiresAt is { } e && now >= e;
}

/// <summary>Click analytics for a link.</summary>
public sealed record LinkStats(int ClickCount, DateTimeOffset? LastClickedAt);

/// <summary>Storage abstraction so the in-memory store can be replaced by a database later.</summary>
public interface ILinkStore
{
    Link Create(string targetUrl, DateTimeOffset? expiresAt = null);
    Link? Get(string code);
    void RecordClick(string code, DateTimeOffset at);
    LinkStats? GetStats(string code);
}

/// <summary>In-memory link store with collision-checked codes, expiry, and click analytics.</summary>
public sealed class InMemoryLinkStore : ILinkStore
{
    private sealed class Entry
    {
        public required Link Link;
        public int Clicks;
        public DateTimeOffset? LastClicked;
    }

    private readonly ConcurrentDictionary<string, Entry> _links = new();

    public Link Create(string targetUrl, DateTimeOffset? expiresAt = null)
    {
        while (true)
        {
            var code = ShortCode.Generate();
            var link = new Link(code, targetUrl, DateTimeOffset.UtcNow, expiresAt);
            if (_links.TryAdd(code, new Entry { Link = link }))
                return link;
        }
    }

    public Link? Get(string code) => _links.TryGetValue(code, out var e) ? e.Link : null;

    public void RecordClick(string code, DateTimeOffset at)
    {
        if (_links.TryGetValue(code, out var e))
            lock (e) { e.Clicks++; e.LastClicked = at; }
    }

    public LinkStats? GetStats(string code) =>
        _links.TryGetValue(code, out var e) ? new LinkStats(e.Clicks, e.LastClicked) : null;
}

/// <summary>Generates URL-safe short codes.</summary>
public static class ShortCode
{
    private const string Alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    public static string Generate(int length = 7)
    {
        var chars = new char[length];
        for (var i = 0; i < length; i++)
            chars[i] = Alphabet[Random.Shared.Next(Alphabet.Length)];
        return new string(chars);
    }
}

/// <summary>Validates that a target URL is an absolute http/https URL.</summary>
public static class UrlValidator
{
    public static bool IsValid(string? url) =>
        Uri.TryCreate(url, UriKind.Absolute, out var uri) &&
        (uri.Scheme == Uri.UriSchemeHttp || uri.Scheme == Uri.UriSchemeHttps);
}
